```tsx components/ThemeToggle.tsx
"use client";

import {
  ActionIcon,
  useComputedColorScheme,
  useMantineColorScheme,
} from "@mantine/core";
import { IconMoon, IconSun } from "@tabler/icons-react";

/**
 * Both icons are rendered and one is hidden per colour scheme with
 * `lightHidden` / `darkHidden`, so server and client markup match.
 */
export function ThemeToggle() {
  const { setColorScheme } = useMantineColorScheme();
  const computed = useComputedColorScheme("dark", {
    getInitialValueInEffect: true,
  });

  return (
    <ActionIcon
      variant="default"
      size="lg"
      aria-label="Toggle light and dark theme"
      onClick={() => setColorScheme(computed === "dark" ? "light" : "dark")}
    >
      <IconSun size={18} stroke={1.75} aria-hidden="true" darkHidden />
      <IconMoon size={18} stroke={1.75} aria-hidden="true" lightHidden />
    </ActionIcon>
  );
}
```

`darkHidden`/`lightHidden` are Mantine component props, not props on Tabler icons. I'll wrap each icon in a Mantine `Box` instead.

```tsx components/ThemeToggle.tsx
"use client";

import {
  ActionIcon,
  Box,
  useComputedColorScheme,
  useMantineColorScheme,
} from "@mantine/core";
import { IconMoon, IconSun } from "@tabler/icons-react";

/**
 * Both icons are rendered and one is hidden per colour scheme with
 * `lightHidden` / `darkHidden`, so server and client markup match.
 */
export function ThemeToggle() {
  const { setColorScheme } = useMantineColorScheme();
  const computed = useComputedColorScheme("dark", {
    getInitialValueInEffect: true,
  });

  return (
    <ActionIcon
      variant="default"
      size="lg"
      aria-label="Toggle light and dark theme"
      onClick={() => setColorScheme(computed === "dark" ? "light" : "dark")}
    >
      <Box component="span" darkHidden style={{ display: "inline-flex" }}>
        <IconSun size={18} stroke={1.75} aria-hidden="true" />
      </Box>
      <Box component="span" lightHidden style={{ display: "inline-flex" }}>
        <IconMoon size={18} stroke={1.75} aria-hidden="true" />
      </Box>
    </ActionIcon>
  );
}
```

`SiteShell` (header, footer, skip link) is used by the root layout, so both routes share it. The header needs the active route, so it is a client component.

```tsx components/SiteShell.tsx
import { Box } from "@mantine/core";
import { SiteFooter } from "./SiteFooter";
import { SiteHeader } from "./SiteHeader";

export function SiteShell({ children }: { children: React.ReactNode }) {
  return (
    <Box
      style={{
        minHeight: "100dvh",
        display: "flex",
        flexDirection: "column",
      }}
    >
      <Box
        component="a"
        href="#main"
        className="skip-link"
        style={{
          position: "absolute",
          left: -9999,
          top: 0,
          zIndex: 1000,
          padding: "8px 12px",
          background: "var(--mantine-color-body)",
          color: "var(--mantine-color-text)",
        }}
        onFocus={undefined}
      >
        Skip to content
      </Box>
      <SiteHeader />
      <Box component="main" id="main" tabIndex={-1} style={{ flex: 1 }}>
        {children}
      </Box>
      <SiteFooter />
    </Box>
  );
}
```

That skip link would stay off-screen even when focused, and `onFocus={undefined}` is noise. Mantine ships a `Button` with `component="a"`, and it has a `visually-hidden`-until-focused pattern through `VisuallyHidden` only for always-hidden content. The simplest correct approach is a small client-free skip link built from Mantine's `Anchor` and the style prop `:focus` handling in CSS, so I'll use a CSS module.

```css components/SiteShell.module.css
.skipLink {
  position: absolute;
  left: 0;
  top: 0;
  z-index: 1000;
  padding: var(--mantine-spacing-xs) var(--mantine-spacing-md);
