  color: var(--mantine-color-text);
  border: 1px solid var(--mantine-color-default-border);
  border-radius: var(--mantine-radius-default);
  transform: translateY(-120%);

  &:focus {
    transform: translateY(0);
  }
}

.root {
  min-height: 100dvh;
  display: flex;
  flex-direction: column;
}

.main {
  flex: 1;
  outline: none;
}
```

