          size={18}
          stroke={2}
          className={classes.check}
          aria-hidden="true"
        />
        <VisuallyHidden>Included</VisuallyHidden>
      </>
    );
  }
  if (value === false) {
    return (
      <>
        <IconMinus size={18} stroke={1.5} aria-hidden="true" />
        <VisuallyHidden>Not included</VisuallyHidden>
      </>
    );
  }
  return <>{value}</>;
}

