            <List spacing="xs" size="sm">
              {points.map((point) => (
                <List.Item key={point}>{point}</List.Item>
              ))}
            </List>
          </Stack>
          <Box className={classes.visual}>
            <FeaturePanel id={id} />
          </Box>
        </SimpleGrid>
      </Container>
    </Box>
  );
}
